// What happened to the product matching by the language model: pending until the crawl ends, disabled
// when no model is configured, skipped when the budget is spent or the site gave no text, then done or
// failed.
// Ref: #/components/schemas/MatchingStatus
type MatchingStatus string

const (
	MatchingStatusPending  MatchingStatus = "pending"
	MatchingStatusDisabled MatchingStatus = "disabled"
	MatchingStatusSkipped  MatchingStatus = "skipped"
	MatchingStatusDone     MatchingStatus = "done"
	MatchingStatusFailed   MatchingStatus = "failed"
)

// AllValues returns all MatchingStatus values.
func (MatchingStatus) AllValues() []MatchingStatus {
	return []MatchingStatus{
		MatchingStatusPending,
		MatchingStatusDisabled,
		MatchingStatusSkipped,
		MatchingStatusDone,
		MatchingStatusFailed,
	}
}

// MarshalText implements encoding.TextMarshaler.
func (s MatchingStatus) MarshalText() ([]byte, error) {
	switch s {
	case MatchingStatusPending:
		return []byte(s), nil
	case MatchingStatusDisabled:
		return []byte(s), nil
	case MatchingStatusSkipped:
		return []byte(s), nil
	case MatchingStatusDone:
		return []byte(s), nil
	case MatchingStatusFailed:
		return []byte(s), nil
	default:
		return nil, errors.Errorf("invalid value: %q", s)
	}
}

// UnmarshalText implements encoding.TextUnmarshaler.
func (s *MatchingStatus) UnmarshalText(data []byte) error {
	switch MatchingStatus(data) {
	case MatchingStatusPending:
		*s = MatchingStatusPending
		return nil
	case MatchingStatusDisabled:
		*s = MatchingStatusDisabled
		return nil
	case MatchingStatusSkipped:
		*s = MatchingStatusSkipped
		return nil
	case MatchingStatusDone:
		*s = MatchingStatusDone
		return nil
	case MatchingStatusFailed:
		*s = MatchingStatusFailed
		return nil
	default:
		return errors.Errorf("invalid value: %q", data)
	}
}

